package ca.yorku.eecs3311.coursepilot.web;
import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.ProgressService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/courses/{courseId}/progress") public class ProgressController {private final StudyAgentFacade facade;private final ProgressService progress;public ProgressController(StudyAgentFacade f,ProgressService p){facade=f;progress=p;}@GetMapping public String page(@PathVariable Long courseId,Model model){model.addAttribute("course",facade.getCourse(courseId));model.addAttribute("progress",progress.summarize(courseId));model.addAttribute("activeNav","progress");return "progress/index";}}
